  str_book_title_saiji_20102 = "Além do Alcance II",
  str_book_title_saiji_20103 = "Além do Alcance III",
  str_book_title_saiji_20104 = "Reflexo na Piscina",
  str_book_title_saiji_20105 = "Espinhos em Movimento I",
  str_book_title_saiji_20106 = "Espinhos em Movimento II",
  str_book_title_saiji_20107 = "Tribunal Suspenso I",
  str_book_title_saiji_20108 = "Tribunal Suspenso II",
  str_book_info1001 = "Dormentes no subterrâneo por 17 anos, (você) e Soroz dependem um do outro. Os resultados da manutenção de rotina concluíram que iniciar a Colossus nesse momento estava fadado ao fracasso, assim como as tentativas anteriores...",
  str_book_info1002 = "Mas as coisas pareciam um pouco diferentes hoje, com a aparição repentina de um intruso. A Percepção é sua habilidade especial como Celestita e, com esse talento, você carrega o peso de vingar sua tribo...",
  str_book_info1003 = "Não havia mais paz na Colossus. Com a invasão de Kraken, um Eclipsita de alto nível, sua tarefa de avançar se tornou mais difícil. Você poderia demonstrar a capacidade que um Navegador deve ter ao enfrentar um inimigo tão forte pela primeira vez?",
  str_book_info1004 = "Assim que você pisou num novo mundo, os Eclipsitas estavam te derrotando. Como diabos apareceram aqui? Seu tempo está acabando, então você precisou retornar para a Colossus para encontrar outra solução...",
  str_book_info1005 = "Olhando para o painel de controle à sua frente, você decide envolver Vice na sequência de inicialização. Você mostra pra Vice como iniciar e completar o dueto juntos.",
  str_book_info1006 = "Olhando para o painel de controle à sua frente, você decide envolver Vice na sequência de inicialização. Você mostra pra Vice como iniciar e completar o dueto juntos.",
  str_book_info1007 = "Olhando para o painel de controle à sua frente, você decide envolver Vice na sequência de inicialização. Você mostra pra Vice como iniciar e completar o dueto juntos.",
  str_book_info1008 = "Com a ajuda de Vice, você finalmente consegue ativar a Colossus. Surtos de Energia fluem assim como a Aurora, a Colossus vagarosamente sobe à superfície. Espere um pouco e estará fora de perigo.",
  str_book_info1009 = "Após ativar a Colossus, memórias do passado começaram a retornar; foi no dia em que seu povo foi destruído em Eraveil, 17 anos atrás. Entre todas as imagens que você viu, uma figura que você jamais esqueceria surgiu...",
  str_book_info1010 = "O perigo estava longe de acabar. Com a derrota do Kraken da Areia, outro Eclipsita de alto nível, Nozard, jurou destruir você, e mais inimigos começaram a se juntar ao redor de Soroz, prontos para acabar com você enquanto se aquece...",
  str_book_info1011 = "Depois de se aquecer, a energia de Soroz fluiu através de seu corpo mais uma vez. Abriu suas asas e lhe livrou dos sufocos da escuridão, de volta aos céus. Os inimigos foram derrubados como poeira, tremendo diante do rugido de Soroz, que proclamava sua ressurreição...",
  str_book_info1012 = "Soroz é forçado a fazer um pouso de emergência na selva depois de se ferir na batalha e de voar pela primeira vez em muito tempo... Enquanto você e Vice discutem, os Eclipsitas invadem...",
  str_book_info1013 = "Rediesel Wrench... O grupo doido de peritos em sobrevivência que você esbarrou abriu seus olhos com relação a sobrevivência básica, companheirismo e conviver consigo mesmo. Mais especificamente, eles cozinham muito mal.",
  str_book_info1014 = "Na zona habitável entre a Luz e a Escuridão, pessoas lutavam para proteger seus lares. Assim como Charon disse, além de Illumina, existem outros Aurorians e povos lutando pelo que amam.",
  str_book_info1015 = "Nozard apareceu de novo, dessa vez comandando mais Eclipsitas do que nunca. O abrigo temporário, Subcidade 28, foi deixado em ruínas por um ataque surpresa. Assim que caiu, um novo capítulo começou...",
  str_book_info1016 = "Nozard ainda estava em uma caçada fervorosa. Para cobrir seus rastros, Charon foi cercado por Eclipsitas. Ele pressionou o botão de autodestruição, o Botão Rubro, para lhe impedir de fazer qualquer besteira. Você não teve escolha a não ser fugir...",
  str_book_info1017 = "Subcidade 28 foi reduzida a ruínas em uma explosão violenta. Enquanto você lamentava a perda de Charon, uma figura familiar apareceu. Era o próprio Charon, que conseguiu escapar num grandioso ato final...",
  str_book_info1018 = "Você estava prestes a descansar, mas recebeu um chamado de ajuda que parecia ser de um compatriota. Depois de chegar em seu destino, foi atacado por Guardiões Colossus, Filex e Vani, que pareciam estar sob o controle de um poder maior...",
  str_book_info1019 = "Sob os ensinamentos de Mendelson, você alcançou a ponte e derrotou Tabaad, com Hiiro desferindo o golpe final. Zakura foi até os céus com pétalas de cerejeira, e essa foi a última visão que Mendelson lembrou...",
  str_book_info1020 = "De acordo com as palavras finais de Mendelson, você deve evitar que um inimigo chamado Schummer encontre o primeiro item: Módulo de Tanque Pensante. Foi sua primeira visita à Lumópolis, o centro da civilização de Astra.",
  str_book_info1021 = "Já que não tem acesso à Lumópolis, você precisa atravessar a Baixa Lumópolis. Pode ser diferente de tudo que imaginou. O perigo permeia o ar. A viagem provavelmente não será fácil.",
  str_book_info1022 = "Por conta da carta de instruções da Vice, você foi pessoalmente recebido por Carleen, a capitã dos Guardiões de Lumópolis. Apesar dessa jovem com cara fechada ser a colega da Vice, ela evitou te olhar e mal prestou atenção em você...",
  str_book_info1023 = "As desordeiras, Shelt e Shire, fugiram pra Cidade Alta mas foram interceptadas por você. Essas duas Eclipsitas estavam preparadas pra briga, mas não tinham ideia do preço que iriam pagar...",
  str_book_info1024 = "Você fez um resumo dos planos de Schummer junto do incidente de Lumópolis na assembleia, mas os oficiais da Federação Illumina foram incapazes de fornecer suporte por alguma razão. Pareceu que você teria que lidar com a batalha do próximo módulo sozinho.",
  str_book_info1025 = "Quando chegou ao lugar em que o segundo Componente foi escondido, como mostrado em seus dados, você se encontrou tomado por uma estranha sensação, que parecia algo como uma ilusão ou um som enfeitiçante – reverberações misteriosas que lhe preencheram com um profundo senso de reverência...",
  str_book_info1026 = "Para obter o segundo módulo, você estabeleceu uma ligação com outro Colossus morto há muito tempo. Visões de antigos Celestitas surgiram diante de você, e seus pensamentos começaram a invadir a sua mente como uma sinfonia.",
  str_book_info1027 = "Para salvar Gronru, você fez um acordo com Schummer e abriu mão do segundo módulo. Inesperadamente, Schummer manteve seu lado da promessa, pois assim como uma antiga patriota, ela parece sentir certa pena de você...",
  str_book_info1028 = "O módulo final foi localizado no misterioso Corredor Suspirante, o relógio está contando e você precisa tomar uma decisão. É um cofre subterrâneo cheio de objetos misteriosos, e você não sabia o que o esperava ali...",
  str_book_info1029 = "A entrada do Corredor Suspirante engolia a luz solar como uma fera desgarrada, e a escada espiral lhe deu um certo tédio. Se Schummer já está por ali, você precisa se apressar...",
  str_book_info1030 = "Gertzurde, que se juntou a Shelt para roubar o primeiro módulo, foi finalmente derrotada por você. Depois de descobrir a verdade por trás da morte de Shelt, seus olhos se encheram de descrença, como se uma parte dele tivesse morrido, enquanto outra nascia...",
  str_book_info1031 = "Nas profundezas do Corredor Suspirante, Schummer preparou seu ataque mortal, mas Gertzurde se manteve resoluto à sua frente. Pálido, conforme a vida deixava seu corpo, mas não era hora de lamentar ou simpatizar. Ainda havia trabalho a fazer.",
  str_book_info1032 = "Com todos os três módulos, Schummer guiou o Colossus Negro num grande ataque à Lumópolis. Apesar do Escudo Lúmina que protegia a cidade, a corneta da blasfêmia ressoou pelos ares...",
  str_book_info1033 = "Ao trabalhar junto dos oficiais da Federação Illumina, o verme da areia gigante, Mara Sol, que tentou invadir Lumópolis, foi completamente derrotado. Pode até ter uma pedra no caminho do inimigo, por enquanto, mas uma crise ainda maior surgiria...",
  str_book_info1034 = "Um Schummer vingativo atacou Soroz, e você foi forçado a abandonar a crise em Lumópolis, rapidamente retornando à Colossus. Era uma cena que deveria ter acabado a 17 anos atrás – o Colossus Branco e o Colossus Negro batalhando novamente...",
  str_book_info1035 = "Um homem encapuzado misterioso estava ao lado de Schummer, o Grande Aviduz. Ao ser repreendido por Vivian, ele revelou seu rosto, e um nome inquestionavelmente ligado à Federação Illumina: Forsakin...",
  str_book_info1036 = "Antes de mais perguntas, Schummer avançou com tudo, e sua força desconhecida levou todos ao chão. Diante de tal perigo, Vivian decidiu tomar uma decisão arriscada...",
  str_book_info1037 = "“As pessoas aqui são tão barulhentas. Só falam besteira. Blah, blah, blah, blah, blah...”",
  str_book_info1038 = "A pedido de Fausto, Vice tomou de você o estranho objeto conhecido como “semente”, dita ser responsável por transformar criaturas em Apóstolos da Escuridão, e também um meio para conceder poderes malignos...",
  str_book_info1039 = "“Por que você não aceita sua fraqueza? Por que não ajoelha diante do verdadeiro poder?”",
  str_book_info1040 = "O canhão de Lúmina, Dâmocles, a arma suprema de Lumópolis, atacou Aviduz com um rugido estrondoso, mesmo com o preço de colocar a cidade em risco...",
  str_book_info1041 = "O raio emanando de Dâmocles, mudou de direção inesperadamente, e Carleen, que tinha pouca Lúmina restante, pareceu incapaz de terminar de conduzi-lo sozinha. Naquele momento, Schwartz, o Senhor da Cidade de Lumópolis, apareceu atrás dela. Juntos os dois proferiram o ataque final contra Schummer.",
  str_book_info1042 = "Graças a sua supressão mental, Aviduz falhou em se desviar do raio de luz que o penetrou instantaneamente. O tempo pareceu parar, e todos pararam como estátuas para presenciar o fim do Colossus Negro...",
  str_book_info1043 = "É uma verdadeira surpresa que um Eclipsite de alto nível viva no Dungeon No. 80 à beira da Noite Eterna. Seu surgimento foi além das expectativas de todos, e também interrompeu os esforços da Vice e da Navigator para reparar o Soroz.",
  str_book_info1044 = "Ela já perdeu sua oportunidade uma vez e não quer desistir desta vez. Somente, quando a mente de seu velho irmão de armas está obscurecida pela raiva e ódio, e quando as memórias das coisas que ele queria proteger e o vínculo com os amigos são ofuscadas, ela ainda pode salvar a sanidade de seu amigo?",
  str_book_info1045 = "Se o mundo foi engolido pelas trevas, e não há mais luz, então eu me tornarei a luz que dissipa as trevas.\nEssa é a escolha de Reinhardt. Ele escolheu ser a luz que brilha em todos os cantos, levando esperança ao lodo do desespero.",
  str_book_info2001 = "Cercado pelos Quatro Anjos, parecia não haver escapatória para Brock e Jona... Mas naquele momento, Jona improvisou uma rota de fuga especial: pular de Lumópolis! Sem pensar nas consequências, pelo menos os dois conseguiram sair de Lumópolis...",
  str_book_info2002 = "Depois de escapar de Lumópolis, Jona e Brock conseguiram reencontrar com as forças da Rediesel Wrench. Diante de seus perseguidores, falaram umas frases de efeito e deram um jeito de escapar nas areias amarelas...",
  str_book_info2003 = "Bowlinger iniciou a autodestruição e Sharona mal conseguiu escapar com Philyshy em seus ombros. Os dois tolos finalmente se reconciliaram, e juntos, lidaram com a ameaça secreta da Cidade Gannon. Philyshy bocejou novamente, mas Sharona não a repreendeu, e as duas escaparam da explosão.",
  str_book_info2004 = "Depois de uma batalha emocionante, Connolly conquistou o pequenino bagunceiro e descobriu um novo significado da palavra “lar”. Foi outro dia sem grandes acontecimentos no ordinário Café Holiday, mas pra Connolly, era uma preciosa parte da vida cotidiana.",
  str_book_info2005 = "Northland, uma planície mágica, onde estrelas cadentes aparecem no céu e decoram os lagos transparentes como cristal. A neve mais pura cobre as florestas Todos densas e planícies sem fim. Um gelada palácio impressionante se impõe sobre o vento gélido, estendendo suas mãos pálidas e delgadas como uma donzela celestial que tenta alcançar a Aurora.",
  str_book_info2006 = "Os esforços de Carleen a recompensam quando ela supera o último obstáculo. Ao derrotar o Eclipsita, ela completa o desafio de Bethlehem. O caminho para se tornar um Guardião é árduo, solitário e reservado àqueles que possuem força verdadeira. No entanto, ao olhar para cima e ver a linda Aurora, uma pessoa pode compreender sua importância irrefutável.",
  str_book_info1051 = "Forsakin e Schummer estavam diante da cápsula de cura.\nForsakin disse a ela que se renunciasse a tudo o que significava ser uma Celestita, poderia ganhar ainda mais poder.\nTudo o que Schummer tinha a dizer sobre o assunto é que ela já havia desistido de ser Celestita há muito tempo...",
  str_book_info1052 = "Para descobrir o paradeiro de Schummer e encontrar uma maneira de consertar Soroz, você voltou para o lar dos Celestitas:\nEraveil",
  str_book_info1053 = "Finalmente, no fundo de Eraveil, você encontrou a Aviduz caída.\nForsakin estava esperando há muito tempo e ela parecia ter algo a dizer.\nOu será que ela estava apenas... ganhando tempo?",
  str_book_info1054 = "A Schummer desperta devorou avidamente os Eclipsitas ao seu redor.\nEmbora o gosto fosse muito nojento, sua determinação de vingança a levou para além de todas as percepções de dor conhecidas.",
  str_book_info1055 = "Tendo obtido um novo poder, Schummer queria que sua professora aceitasse esse presente, mas ela não conseguia escapar de suas amarras.\nNo entanto, tal laço não poderia impedir Schummer, e ela acreditava que os Celestitas acabariam pedindo uma segunda chance.",
  str_book_info1056 = "Através da subjugação interna e externa, Eraveil caiu.\nOs Eclipsitas invadiram sem parar, proclamando a grande vinda do Eclipse.",
  str_book_info1057 = "Alimentada por um desejo incontrolável, Schummer ultrapassou o limite da Semente, e Forsakin finalmente alcançou seu objetivo.\nEla pegou a semente de Schummer sem hesitação e saiu.",
  str_book_info1058 = "Schummer ordenou que os Eclipsitas matassem todos enquanto estavam ocupados recuperando os Módulos.\nMas por ter perdido sua Semente, logo foi cercada por Eclipsitas e morreu em meio a um mar de caos escuro e cambiante.\nSeu fim refletiu o sofrimento levado a seu povo há dezessete anos.",
  str_book_info1059 = "Em seus últimos momentos, Schummer retomou parte de sua consciência.\nVocê testemunhou as sombras do Eclipse. Embora tenha sido apenas por um momento, a extensão do poder que você sentiu era inquestionável...",
  str_book_info1060 = "Com um barulho alto, a porta se abre lentamente diante de você. Segredos que foram enterrados sob o Eraveil por toda parte estão esperando para serem descobertos por você.",
  str_book_info1061 = "O Atacante Especial é ativado para lidar com Eclipsitas, mas também tem como alvo Aurorianos. Vice é atingido por ele tentando protegê-lo.",
  str_book_info1062 = "Você chega à área central nas profundezas da base subterrânea e encontra o Sistema Circular que controla toda a base. Esta máquina estranha pode apenas saber como salvar Vice que entrou em hibernação.",
  str_book_info1063 = "A Torre do Retorno se ergue em choques violentos, revelando sua aparência original.\n\"Esta Torre Branca nunca deveria estar aqui. Deveria estar... em algum lugar muito mais alto.\"",
  str_book_info1064 = "A Torre Branca erguida tornou-se a estrutura mais alta de Eraveil. Fica aqui enquanto você consegue ver o mundo inteiro através dele.",
  str_book_info1065 = "As recentes mudanças geológicas tornaram o caminho para a Chord Zone acidentado e áspero. Cada passo no túnel cheio de armadilhas é extremamente difícil. Para curar Vice, no entanto, você tem que superar todas as dificuldades que estão em seu caminho.",
  str_book_info1066 = "Barton ganhou um novo poder do Chord Link, que lhe permite mais uma vez enfrentar Forsakin e virar a maré. Com a ajuda dele, você vai embora Forsakin e coloque Vice no Chord Link, esperando que isso a cure...",
  str_book_info1067 = "Eraveil está em uma crise sem precedentes. A Torre do Retorno sendo cercada por Eclipsites lembra o dia em que Eraveil foi atacado. Mas desta vez é diferente. Amigos e aliados de todo o mundo vieram em seu auxílio.",
  str_book_info1068 = "Vice que entrou em hibernação foi colocado no Chord Link para tratamento. Dê-lhe tempo e tenha fé que ela vai acordar.",
  str_book_info1069 = "Carleen e você teceu um casulo usando as camadas de defesa da Torre do Retorno, para proteger Vice que está dentro do Chord Link para garantir que ela acordará como planejado. Agora é a hora de quebrar o casulo.",
  str_book_info1070 = "Seus aliados estão mantendo os Eclipsites fora da torre para garantir que a operação corra bem. Começa uma batalha entre a Rainha do Norte, que veio de longe, e Figelo. Cada segundo conta agora. Encontre uma oportunidade para virar a maré e trazer vitória e esperança para esta batalha.",
  str_book_info1071 = "Vice que despertou do Chord Link parece ter ganhado novas habilidades. Suas mentes estão conectadas neste momento. Você a protegeu todo esse tempo, e agora ela lutará por você.",
  str_book_info1072 = "Enquanto a batalha de Eraveil acabou por enquanto, todos têm opiniões diferentes sobre o que fazer com a Torre do Retorno. No final, eles conseguem chegar a um acordo - A Torre do Retorno pertence a Eraveil e aos Caelestites.",
  str_book_info1073 = "Você encontra Sean, Crow e Zhao no centro médico Illumina. Eles vieram de uma cidade remota chamada Twilight localizada fora da linha de defesa de Illumina...",
  str_book_info1074 = "Quatro pesquisadores do ultrassecreto Conselho de Ciências da Illumina estão esperando por você. Como esse encontro secreto mudará o seu destino e o de Soroz?",
  str_book_info1075 = "Você vê Soroz novamente no espaço de dados. Está na sua frente, mas você não pode tocá-lo. Até a proximidade é falsa.",
  str_book_info1076 = "De acordo com registros antigos, os Colossos retornaram dos céus. O mundo há muito se tornou desconhecido, deixando-os sem escolha a não ser procurar vestígios do passado.",
  str_book_info1077 = "Quando a Aurorastorm surge fora de controle, os cavaleiros rasgam o céu carmesim como brilhantes cometas prateados. Com o decoro dos Nobres Lumo não mais sendo levado em consideração, esses cavaleiros robustos vestem suas armaduras de ferro pontiagudas em defesa do povo.",
  str_book_info1078 = "Você entra em Crepúsculo e não sabe onde procurar. Pessoas sem-teto vagam pelas ruas, vendedores apregoam seus produtos e cavaleiros Lumo e soldados Illumina caminham lado a lado nas ruas.",
  str_book_info1079 = "Sean decide desafiar Axelia para ver quem consegue derrotar mais Eclipsites. No final, Axelia vence!",
  str_book_info1080 = "Este Colosso está enterrado aqui há tantos anos que quase se fundiu completamente com as rochas ao seu redor. Um gigante que uma vez voou nos céus azuis nunca mais abrirá suas asas...",
  str_book_info1081 = "Quando você retorna, um Wraith que você nunca conheceu antes está em seu caminho. Ela tem grande poder e um motivo estranho. Ela parece querer destruir todos os \"desejos\" do mundo.",
  str_book_info1082 = "— Nos encontramos de novo, celestita. Não vou me conter, já que você veio e se entregou diretamente a mim.",
  str_book_info1083 = "Para completar seu experimento e coletar dados, Forsakin decide usar Vice para descobrir o segredo do Chord Link. Quando você tenta impedi-la, você é preso ao chão pelo animal de estimação que ela carrega para todos os lugares.",
  str_book_info1084 = "Yingel joga seu trunfo contra Forsakin e Helios - ela ameaça Forsakin com a destruição do Chord Link. Diante do desdém e desprezo da outra parte, Yingel puxa o gatilho.",
  str_book_info1085 = "Pensando que o laboratório foi destruído, Forsakin abandona apressadamente seus reféns para resgatar o laboratório, apenas para perceber Yingel a enganou.",
  str_book_info1086 = "Forsakin usa três métodos de aprimoramento diferentes para transformar Helios na existência mais forte. Agora é hora de testar a estabilidade do sujeito matando coisas.",
  str_book_info1087 = "O Exercício Militar Conjunto é realizado conforme programado, e participantes de Lumopolis, Illumina, Twilight e todos os outros lugares se reúnem aqui para lutar pela coroa.",
  str_book_info1088 = "Contra ondas de Eclipsites no Battle Simulator, a equipe de Leo ainda consegue sair vitoriosa, chocando a todos com seu poder.",
  str_book_info1089 = "Os membros da equipe de Leo parecem ter exposto uma fraqueza na batalha final de captura da bandeira. Yingel agarra decisivamente esta oportunidade fugaz para pôr fim à batalha.",
  str_book_info1090 = "A equipe de Yingel, os campeões, enviam Axelia para participar de uma partida de exibição com Reinhardt. Subcorrentes surgem sob a atmosfera aparentemente pacífica do local.",
  str_book_info1091 = "Mesmo que você pare Figerald, um misterioso Wraith tira o console central do Guardian One e diz algo vago na frente de todos. Quem é ela?",
  str_book_info1092 = "Na sala de interrogatório em Illumina, o Caso de Traição Reinhardt passa por seu terceiro escrutínio interno. A outrora reverenciada Grande Marechal Reinhardt, agora acorrentada, olha silenciosamente para os espectadores.",
  str_book_info1093 = "Ao fazer uma entrada grandiosa como a nova Grande Marechal, Wrath, ela está cercada pela Legião da Guarda e pelas armas de última geração: Engine VII. Soldados se maravilham com sua graça imparável, mas uma mistura de emoções agita seu coração.",
  str_book_info1094 = "O pântano rói implacavelmente a terra, emitindo estalidos ensurdecedores. Montes de terra ao redor desmoronam, a vegetação murcha e um cheiro pungente enche o ar. É como uma imensa teia aprisionando criaturas inocentes.",
  str_book_info1095 = "Dentro do atoleiro que se espalha rapidamente, a boca vermelho-sangue de um Eclipsita surge repentinamente. Ele se enfurece selvagemente, preparando-se para devorar tanto a terra quanto os Aurorianos. Os soldados entram em pânico, espalhando-se em todas as direções.",
  str_book_info1096 = "Mergulhada em uma escuridão sem limites, Wrath tem apenas um fraco brilho ao seu redor para contar. É a semente incrustada em suas costas, como uma broca, drenando implacavelmente sua força vital. Quanto mais frágil ela se torna, mais deslumbrante é o brilho da semente.",
  str_book_info1097 = "A expansão da semente se desdobra como o desabrochar requintado de uma delicada flor de espinhos dentro da forma de Wrath. Ela sente a sensação de picadas, semelhante a correntes de ferro se apertando ao seu redor, como se fosse um castigo por seu duelo perdido.",
  str_book_info1098 = "Embora Axelia não sinta dor física, a angústia emocional aumenta sutilmente cada vez que ela testemunha a queda de um soldado. Um, dois... ela conta silenciosamente o número de mortes, dando origem à ilusão de que ela mesma pereceu onze mil, cento e onze vezes.",
  str_book_info1099 = "No céu azul, várias deslumbrantes faixas de luz branca passam rapidamente. Joselyne, em cima de um cavalo de guerra branco como a neve e empunhando uma lâmina afiada, avança ao lado dos Lumo Skyriders, rumo ao atoleiro. O céu ecoa com o relinchar dos cavalos.",
  str_book_info1100 = "O Navegador pilota o Colossus até o local designado para realizar uma missão. Depois que o Colossus voa para uma altura segura para a descida final, Caelestites e Eclipsitas começam a descer do céu. Isso é um sonho, ou isso realmente aconteceu antes?",
  str_book_info1101 = "No céu tingido de vermelho pelo pôr do sol, através de camadas de nuvens e névoa, um buraco negro que pode devorar tudo observa você. Parece estar tentando te dizer algo, e você percebe que ele deixou uma marca negra escura em sua mente depois que você acorda.",
  str_book_info1102 = "Muitos pilares de pedra congelados parecem estar crescendo em direção ao céu. Algum tipo de força parece estar guiando-os para alguma forma no ar. Por que uma cena como essa apareceria na mente de um Illuminan que quase nunca sai de casa?",
  str_book_info1103 = "Um dia, um ano... três anos, e então dez anos... Naquela era de guerra, o jovem Ulysses procurou na sala de evidências a esperança de sobrevivência dos Aurorianos - esperança que vem de um nome que foi apagado da história de Illumina.",
  str_book_info1104 = "Após 40 anos de pesquisa, 20 dos quais foram gastos compilando um banco de dados genético especial, este armazém está cheio de criações Ulysses preparadas especialmente para este momento para lutar contra o inimigo.",
  str_book_info1105 = "Inimigos estão correndo à solta na Cidade de Gannon para encontrar e eliminar o Caelestite. Justamente quando eles se aproximam do Caelestite, o pequeno e discreto companheiro do Caelestite bloqueia um golpe pesado de um inimigo para o Caelestite sem qualquer hesitação.",
  str_book_info1106 = "\"Não deixe que eles te controlem! A sabedoria não tem restrições!\" Algol grita enquanto sua mente opera em alta velocidade com Bool. Ela quer dizer a todos que eles não precisam viver em um mundo que está constantemente ameaçado pelo desconhecido.",
  str_book_info1107 = "As viagens são sempre misteriosas e mágicas quando se viaja com a Senhora Victoria. Ela disse que agora que o Rio Prístino foi despertado e Eoria precisa começar um novo capítulo, essa existência especial é necessária para guiar a todos da mesma maneira.",
  str_book_info3060 = "O golpe decisivo foi dado! Smokey deu um pulo alto! Antes que alguém tivesse chance de reagir, a bola de vôlei atravessou a quadra como uma bala, atingindo seu oponente em cheio!",
  str_book_info3061 = "A estranha competição se tornou uma batalha de armas de água, e todos estão dando tudo de si!",
  str_book_info3062 = "A última prova do Monarca do Oceano foi uma apresentação na praia! Os Aurorians estavam se revezando nas apresentações no palco e, finalmente, o trio de Smokey, Carleen e Vice: \"Beijo da Manticora\", fizeram uma performance que eletrizou o público.",
  str_book_info3063 = "Os sinais da crise ainda permaneciam, e Beryl desapareceu de repente! Quando você finalmente a encontrou, ela estava em um mundo de perigo!",
  str_book_info3064 = "Quando toda esperança estava perdida, Raphaela saltou do penhasco e pegou Beryl no ar. Os anjos podem mesmo voar!",
  str_book_info3065 = "Depois que Raphaela pegou Beryl, ela usou seus jatos para desacelerar a descida. Como alguém poderia abandonar seus amigos por causa de algo como perigo mortal?",
  str_book_info3066 = "Bonacie regeu uma melodia proibida na superfície do mar para seus Avatares Sagrados interpretarem. Enquanto faziam isso, o castelo adormecido no fundo do mar se ergueu atrás dela, e um enorme meteorito caiu do céu, indo direto para nossos heróis, a praia e a hospedaria!",
  str_book_info3067 = "Quando parecia que tudo estava perdido, Fleur tomou controle de seu novo robô gigante e suportou o impacto do meteorito com as mãos! Que tipo de poder estranho é esse?",
  str_book_info3068 = "A crise foi evitada. Fleur ordenou que seu Rediesel Steel MkV ficasse na frente de todos e bloqueou as ondas.",
  str_book_info3069 = "Durante a audiência final, a equipe Colossus ficou em desvantagem diante do poder formidável do Rei e de Caroline. Caroline revelou seu segredo para Beryl, que havia descoberto a verdade com Raphaela, lutou com todas as suas forças.",
  str_book_info3070 = "Tendo rompido a magia do inimigo sozinha, Beryl usou toda sua força para lançar um ataque final e derrotou o Rei e Caroline com a ajuda de seus amigos.",
  str_book_info3071 = "No deserto, uma construção de aço de Illumina se destaca, a Estação da Subcidade 24. De acordo com nossos relatórios, essa estrutura é usada como um campo de treinamento para novos recrutas, assim como um centro de transporte, contendo depósitos e outras instalações.",
  str_book_info3072 = "O poderoso chefe Eclipsita foi destruído, e naquele momento todos pensaram a mesma coisa: a hora do confronto chegou!",
  str_book_info3073 = "O Oficial Brent lidera os soldados no confronto com os Eclipsitas. Porém, um tentáculo surge do chão e perfura seu coração.",
  str_book_info3074 = "Havia um tempo em que Gram não conseguia pensar em uma maneira de dizer adeus aos seus irmãos de guerra.\nAgora, confrontado com o sacrifício de Brent, Gram jura prosseguir com a convicção inabalável de Brent, prometendo continuar a luta até a vitória!",
  str_book_info3075 = "Um Eclipsita gigante voador conhecido entre sua espécie como Hylingerr ataca a Subcidade 23. Inabalados pelo poder aterrorizante de seu inimigo, o povo da Subcidade 24 enfrenta o inimigo de frente, movidos por determinação e fúria.",
  str_book_info3076 = "As comunicações foram finalmente restauradas, e todos aguardam ansiosamente por notícias da batalha. Após um curto tempo, Reinhardt, a Grande Marechal de Illumina, aparece na tela e anuncia que a Linha Dunafogo foi restabelecida com sucesso e que Illumina foi vitoriosa.",
  str_book_info3077 = "Antes de todos saírem da Subcidade 24, o oficial chefe propõe uma foto em grupo, para eternizar esse dia histórico. A foto registra os sorrisos dos soldados, a luz da esperança infinita de Brent e o esplendor de Illumina.",
  str_book_info3078 = "Encarado com uma ofensiva do exército Eclipsita, o Oficial Brent explica o objetivo do esquadrão da Subcidade o mais claro possível. Tudo que precisam fazer é lutar contra o exército Eclipsita e defender a Subcidade!",
  str_book_skin_info_1001 = "As coisas existem neste mundo porque acreditamos nelas, ou acreditamos nelas porque existem?\nVerdade ou mentira, fato ou ficção...\nO castelo que Kleken mencionou realmente está no fundo do mar, ou é apenas mais uma de suas histórias?",
  str_book_skin_info_1002 = "Vice planeja ganhar um dinheiro extra na viagem, então ela começa a testar várias tentativas interessantes...\nComo um bom amigo, por que não dá a ela algum incentivo, ou talvez algumas sugestões?",
  str_book_skin_info_1003 = "Claramente com medo do mar, Carleen fecha os olhos ao entrar na água...\nFelizmente, sua mão estendida lhe dá um pouco de coragem e ela finalmente abre os olhos para apreciar a beleza do oceano com você.",
  str_book_skin_info_1004 = "Um presente que pode trazer felicidade verdadeira não tem preço... Essa é a filosofia de Eicy\nPara retribuir o presente inestimável que você deu, ela preparou um monte de guloseimas e as entregou pessoalmente...\nO problema é que esses presentes são um pouco doces demais para o gosto de qualquer pessoa.",
  str_book_skin_info_1005 = "O naufragado Barton chega em uma ilha deserta, recusando-se a sucumbir às profundezas do oceano.\nEnquanto puder respirar, seu treinamento deve continuar!\nPara conquistar os mares um dia, Barton e seus dois lobos brancos correm pela praia, com um vigor obstinado.",
  str_book_skin_info_1006 = "Conforme olha o deserto desolado, Hiiro coloca o uniforme antigo da Academia Militar de Illumina, que você havia entregado.\nUma expressão incomum passa pelo seu rosto, ficando tão gentil quanto o céu estrelado.",
  str_book_skin_info_1007 = "Um cemitério está escondido nas profundezas da floresta.\nSharona conta a você que esse é o lugar de descanso de seu falecido povo.\nEla enfatiza o fato que, apesar de serem seu povo, eles não eram sua família.",
  str_book_skin_info_1008 = "Sob as ordens de Hiiro, Vice acende os estalinhos pela primeira vez.\nSuas pequenas faíscas dançam pelo silencioso céu noturno e iluminam o rosto de Vice, que é tomado por empolgação.\nSe esse momento pudesse durar para sempre.",
  str_book_skin_info_1009 = "Enquanto chamas furiosas o cercam, nosso herói quebra a janela sem pensar duas vezes!\nEste é o clímax magnífico da cena final de tirar o fôlego.\nSe você estivesse assistindo da platéia, aplaudiria de pé.\nInfelizmente, você é a personagem principal dessa vez.",
  str_book_skin_info_1010 = "O castelo de areia se transforma em gotas de água que refletem o sol poente em um caleidoscópio de rosas e vermelhos, mas essa bela imagem não é tão pitoresca quanto seu sorriso.",
  str_book_skin_info_1011 = "Não importa o quanto Pact se esforce para se libertar dos espinhos, eles ficam cada vez mais fortes.\nNeste momento, você abre a porta e vê a situação com seus próprios olhos.\nPact enrubesce e grita: \"Não olhe para mim! Eu posso cuidar disso sozinha!\"",
  str_book_skin_info_1012 = "Não tem como escapar!\nMigard arrasta você para o quarto dela.\nEste salão estranho está cheio de plantas esquisitas, aparatos e materiais científicos.\nParece... nada surpreendente.",
  str_book_skin_info_1013 = "As plantas verdes balançam levemente sob o sol do meio-dia.\nFios de pelo de gato flutuam no ar.\nDormindo profundamente ao sol, desfrutando de um belo sonho felino.",
  str_book_skin_info_1014 = "Quando o relógio marca meia-noite, a ilusão mágica é gentilmente removida pelo tempo.\nUm belo vestido de festa se transforma em um caleidoscópio de borboletas, batendo asas intensamente na luz quente.\nAté a última dança chegar ao final.",
  str_book_skin_info_1015 = "Conforme os laços magníficos dançam no ar, o espírito da estação se estabiliza lentamente.\nAnimação, antecipação e inquietação são sentidas.\nApós aguentar a contagem regressiva cheia de suspense, ninguém pode rejeitar a alegria do tempo presente para finalmente abrir os aguardados presentes!",
  str_book_skin_info_1016 = "Conforme os ecos distantes da celebração se aproximam da costa, eles são espalhados pelos ventos no Lago Espelho.\nNikinis abaixa sua cabeça para observar a superfície do lago…\nMas ela não vê sua irmã em lugar algum. Em vez disso, ela se depara com o seu reflexo transparente de cristal.",
  str_book_skin_info_1017 = "A vida é como uma ilusão em um espelho.\nDesejo, vontade de ter algo que não pode ser seu.\nQuando pensamentos turbulentos penetram na sua mente, a melhor solução é esfriar a cabeça no meio do mar de caos e mergulhar em um sono tranquilo.",
  str_book_skin_info_1018 = "“Deixar as preocupações de lado não é tão difícil como parece.”\nA garçonete riu alegremente.\n“Tudo que você precisa é um quarto confortável, uma bebida quente e alguém para conversar com você.…”\n“E, é claro, uma boa noite de sono.”",
  str_book_skin_info_1019 = "A coragem de um lagarto! Sob a luz do sol ofuscante e o vasto deserto, Maggie apareceu com ousadia e até fez o artista voar. Não só chocou o público, mas também os deixou com uma impressão profunda.",
  str_book_skin_info_1020 = "Aviso! Eva está em perigo! Depois de colocar essa roupa estranha, não importa onde Eve esteja, sempre que ela ativa o dispositivo, Sinsa imediatamente aparece ao seu lado como um pai amoroso e velho... Oh espere, quero dizer como um irmão mais velho.",
  str_book_skin_info_1021 = "Depois de muita reflexão e ponderação à luz do sol poente, Uriel, como sempre, estava perdida em seus pensamentos sobre o nada. A única coisa que pode salvá-la é a sua companhia. Não importa o resultado, o que importa é o tempo que passamos juntos.",
  str_book_skin_info_1022 = "Bom ou mal? Sariel, que busca a simetria em tudo, prefere rasgar uma meia perfeitamente boa para conseguir o que ela chama de simetria perfeita.",
  str_book_skin_info_1023 = "Carleen vestiu uma roupa completamente diferente para a festa do pijama de seu habitual eu solene e sério! Mas não olhe para ela porque até o comandante cavaleiro também entraria em pânico.",
  str_book_skin_info_1024 = "Shinnosuke é um samurai do leste. Para restaurar o bem-estar de sua irmã — Eva, ele prometeu eliminar todos os males. Durante sua jornada, ele conhece seu inimigo - o Caelestite, e os dois embarcam em uma luta até a morte. Quem será o último de pé?",
  str_book_skin_info_1025 = "Vivian vestiu a roupa de Cloud Mountain e assumiu temporariamente o cargo de proprietária do Cloud Blossom Hotel. Com a ajuda dela, a pousada geralmente deserta fervilhava de hóspedes. No entanto, ela deve aprender a descansar mais!",
  str_book_skin_info_1026 = "Vestindo uma roupa de combate especial, Wrath chegou a Cloud Island e começou sua missão de investigação. Só que essa roupa não é um pouco chamativa? “Isso deve ser ideia do Hiiro!” – disse o Comandante da Legião Wrath.",
  str_book_skin_info_1027 = "Uma donzela extravagante fica na plataforma com seu guarda-sol branco enquanto escreve seu desejo em um cartão postal. Teria sido um feriado maravilhoso se nenhum imprevisto tivesse ocorrido. Mas acho que um juiz chefe confiável está sempre de prontidão!",
  str_book_skin_info_1028 = "Connolly tenta ser líder de torcida, mas se vê incapaz de se sentir confortável em sua roupa. Graças ao incentivo das pessoas ao seu redor, ela decide superar seus escrúpulos com um \"treino\" especial, mas depois começa a chover...",
  str_book_skin_info_1029 = "A nova roupa que Istvan pretendia usar para o evento é substituída por uma camisa floral. Apesar da zombaria que causa, ele consegue uma atuação perfeita no dia do evento que tira as palavras da boca dos adversários.",
  str_book_skin_info_1030 = "\"A mera força não substitui o poder da justiça.\" Não há necessidade de seguir as regras sem sentido de uma partida duvidosa ou se preocupar com classificações falsas. Basta dar tudo de si e sair com uma atitude despreocupada.",
  str_book_skin_info_1031 = "Taki está na liderança quando o rali chega ao grupo Umbraton. No entanto, seus oponentes se recusam a ser superados e usam algum tipo de \"arma letal\" para parar seu carro...",
  str_book_skin_info_1032 = "Louise está relaxando na grama, saboreando um delicioso chá da tarde com seu \"mestre\". Em suas palavras, a vida de uma empregada deve ser tão cheia de alegria e inocência - foi o que Lita disse a ela.",
  str_book_skin_info_1033 = "Thump Thump Thump... O acidente fez o coração de Bethel bater como um trovão. Isso é o medo do perigo ou a emoção da inspiração? Ou é por causa de uma paixão? Isso... talvez possamos ter um vislumbre da resposta do romance de Bethel.",
  str_book_skin_info_1034 = "Fleur pegou o pão recém-assado, abaixou a cabeça e deu uma mordida, depois mastigou com cuidado. De repente, ele congelou no lugar, os olhos cheios de lágrimas...\n\"Obrigado por me ajudar a encontrar esse sabor quente.\"",
  str_book_skin_info_1035 = "Isso não é brincadeira. Repito, isso não é brincadeira! Este é um exercício tático repentino de empregada doméstica. Os prisioneiros que invadirem a mansão serão levados à justiça e colocados na prisão. Todas as empregadas, incluindo a empregada-chefe, todas têm total confiança nisso.",
  str_book_skin_info_1036 = "A maioria das pessoas acha as coisas arejadas e sonhadoras calmantes e Leona não é exceção. Ela encontra rara paz de espírito quando encapsulada por uma bolha gigante, que talvez seja um estado de espírito que ela procurava há muito tempo.",
  str_book_skin_info_1037 = "Há algo sobre ela que é tão deslumbrante e de tirar o fôlego quanto uma jóia. Testemunhas acham difícil identificar a fonte exata de seu charme.",
  str_book_skin_info_1038 = "Se alguém na ilha comete o mal e ninguém ouve as queixas da vítima, a vítima pode despejar suas queixas ao mar, que enviará emissários para presidir a justiça. Desta vez, aquele que foi enviado é...",
  str_book_skin_info_1039 = "É extremamente cruel e egoísta pregar um \"arco-íris\" em uma caixa de madeira para manter sua beleza só para você. Se você realmente quer apreciar esse arco-íris, deve deixá-lo dançar livremente.",
  str_book_skin_info_1040 = "Águas claras e criaturas aquáticas nadando livremente... Ao olhar para eles, Gronru parece ser capaz de esquecer sua identidade e os jogos que ela adorava. Neste momento, ela é apenas uma garotinha que está feliz depois de ver algo em que está pensando.",
  str_book_skin_info_1041 = "Nadando no deserto, você diz? Nada é impossível! Os membros do Rediesel Wrench estão realizando um festival de água no Oasis. E a entrega pontual do pedido da Azure traz a atmosfera festiva para um novo nível.",
  str_book_skin_info_1042 = "\"Eu deveria estar tirando todas as vidas sem pensar duas vezes.\" E-Espere, o que é isso? Apontando uma arma para um velho amigo?! O que você está fazendo, Caronte?! O olhar em seus olhos me diz que ele não está fingindo...",
  str_book_skin_info_1043 = "\"Os vivos contam mil mentiras, mas os mortos não contam nada além da verdade. Uma pena que ninguém possa ouvir suas vozes.\" Ignorando os olhares de lado e os sussurros dos outros, Sikare ajuda a descobrir a verdade para dar voz ao falecido.",
  str_book_skin_info_1044 = "Embora ela não pertença à Federação Illumina, o novo uniforme de xerife Illumina de Hedy a enche de confiança e senso de dever. Como tal, até seu discurso conquista o respeito e a admiração das massas.",
  str_book_skin_info_1045 = "\"Esta foi uma decepção maior do que eu pensava...\" Mesmo em um lugar perigoso cheio de criminosos endurecidos, o poder de Revy a faz ficar muito acima do resto. Quando alguém é tão invicto em força, a falta de competição deve ser solitária às vezes.",
  str_book_skin_info_1046 = "\"Chefe, isso é para você.\" Com seu segundo em comando e outros membros, Paloma parece uma líder de gangue. Sob os olhares rápidos de todos, ela já pensa em como responder ao pedido do visitante.",
  str_book_skin_info_1047 = "Embora Shaya também tenha mostrado um lado teimoso e infantil na história, ela agora está focada, responsável e muito determinada, assim como Bethlehem, e encantadora de uma maneira diferente.",
  str_book_skin_info_1048 = "Reúna-se, todos, pois o Justiceiro está aqui! A punição na forma de luzes piscantes e trovões sonoros a acompanham enquanto ela bate na sua frente! Sob sua vigilância afiada, ninguém escapará!",
  str_book_skin_info_1049 = "\"Esta peça é dedicada a todos na platéia.\" A música lhes traz calor e bênçãos nesta noite fria de inverno. E para um público especial, também traz reconhecimento e encorajamento.",
  str_book_skin_info_1050 = "Para obter uma vantagem, Siobhan calcula os dados de todos os competidores e rapidamente formula sua própria estratégia - desenvolver seu charme usando roupas e maquiagem e dominar as audições.",
  str_book_skin_info_1051 = "Um romântico? Muito serio? Talvez o comportamento seja apenas uma fachada. Pittman mostra seu lado doce quando dois corações anseiam um pelo outro, e a pomba branca é o testemunho disso.",
  str_book_skin_info_1052 = "A famosa Thunder Knight fez jus ao seu nome ao atingir o \"inimigo\" com um raio em um piscar de olhos. Para sua surpresa, no entanto, o cara confessou seu amor por Michael do nada...",
  str_book_skin_info_1053 = "Ela é dona do salão e banqueira e participante do jogo. Jeno agora entende as regras aqui. Depois disso, ele mostrou ao seu desprezível oponente a verdadeira magia, criando um milagre que mandou a carta do Coringa para onde deveria ir.",
  str_book_skin_info_1054 = "\"Todos vocês - vocês estão todos presos!\" Quando se depara com um suspeito tolo o suficiente para tentar perseguir sua irmã, Dayna optou pela solução mais direta e eficaz - prender todos os presentes e não deixar nenhum deles ir.",
  str_book_skin_info_1055 = "Poderia aquela presença inignorável espreitando atrás Fia na escuridão realmente ser um dragão...? Depois de se acalmar o suficiente, ela percebe que é apenas algum tipo de dispositivo... mas quem o controla?",
  str_book_skin_info_1056 = "A melhor maneira de lidar com uma pessoa verdadeiramente desprezível é usar seus próprios truques sujos contra ela - dar-lhe o gosto de seu próprio remédio. E quando eles finalmente perceberem o quão traiçoeiros e vis eles são, já será tarde demais.",
  str_book_skin_info_1057 = "Em meio a um mar de flores, os caídos Cuscuta enlaça o criminoso perverso e o arrasta para o abismo da perdição, enquanto a fragrância se torna um canto fúnebre para o pecador.",
  str_book_skin_info_1058 = "\"Não fuja de mim.\" Eicy diz com um sorriso inocente, enquanto navega calmamente pela multidão frenética. Apesar de ser o mentor de tudo, à sua maneira, ela vê isso como um ato de misericórdia.",
  str_book_skin_info_1059 = "Acontece que o feitiço proibido inscrito no grimório é na verdade a receita de um prato delicioso. Ingredientes inusitados misturam-se harmoniosamente, criando um sabor extraordinário que confere uma essência divina a quem o prova.",
  str_book_skin_info_1060 = "Nem todos os que possuem grande poder são maus. Tudo depende de como esse poder é exercido. A fim de salvaguardar a inocência das crianças, Gabriel toma uma decisão resoluta e descobre a motivação para perseverar.",
  str_book_skin_info_1061 = "Parece que Rinne está pedindo ajuda a seus amigos depois de ser ferido e promete retribuir bem de acordo com os costumes da Ilha Cloud. No entanto, essa pessoa é realmente Rinne?",
  str_book_skin_info_1062 = "Paloma não se importa nem um pouco com as opiniões dos outros e nunca se preocupa com convenções mundanas. Ela apenas abraça tranquilamente as vibrações costeiras, exibindo com confiança sua roupa, enquanto seu charme se dispersa graciosamente.",
  str_book_skin_info_1063 = "Quando você faz um desejo em um dente-de-leão intacto e depois sopra, seu desejo se tornará realidade assim que a primeira semente de dente-de-leão pousar. Ela sussurra em sua mente e observa o floco branco. Naquele exato momento, o desejo já se tornou realidade.",
  str_book_skin_info_1064 = "A exploração de ruínas é repleta de perigo, especialmente debaixo d'água, onde até mesmo a aparentemente inofensiva grama aquática pode se tornar um laço mortal. Felizmente, Florine está aqui, garantindo que tais cenários nunca aconteçam.",
  str_book_skin_info_1065 = "As ondas trouxeram a garrafa à deriva até as mãos dela. Sem um destinatário específico, a garrafa à deriva não é um meio de transmitir mensagens, mas simboliza o desejo de alguém. Porém, neste exato momento, parece que as ondas não são mais apenas ondas, mas sim um membro da estimada União Mensageira.",
  str_book_skin_info_1066 = "Os dragões de gelo deslizam pelo ar árido, trazendo brisas refrescantes, e na superfície do mar, cristais frios e reluzentes começam a se condensar... Apenas o poderoso Queen do Norte poderia criar uma cena tão maravilhosa e magnífica em uma praia escaldante no auge do verão.",
  str_book_skin_info_1067 = "Essas águas-vivas flutuantes parecem ser incríveis aos olhos de todos, mas o mar luminescente que elas formaram aqui e agora é ainda mais fantástico do que se poderia ver em qualquer conto de fadas.",
  str_book_skin_info_10045 = "Ela é a juíza-chefe elevada, distante e séria para todos os outros. Mas agora, ela está mostrando um lado completamente diferente dela, que ela mantém bem escondido sob sua máscara...",
  str_book_skin_info_10046 = "À medida que a chuva cessa e o sol aparece, os dois caminham pela orla úmida.\nVendo as nuvens escuras se dissiparem gradualmente, um raio de sol brilha no mar azul e na areia dourada.\nA única coisa mais maravilhosa do que isso seria se eles também pudessem ver essa bela paisagem.",
  str_book_skin_info_10047 = "Cercada por ambientes que estão sempre mudando, o som arrepiante de um relógio e essa ilusão repentina...\nSanae está apavorada.\nÉ apenas ficando perto do Navigator que ela tem coragem para continuar seguindo em frente.",
  str_book_skin_info_10048 = "Nina ainda sente que muitas de suas ideias não foram realizadas após tirar várias séries de fotos.\nEla decide seguir o conselho do Navegador e descansar após seu trabalho agitado, mas a melancolia ainda a assombra.",
  str_book_skin_info_10049 = "Connolly sai do provador ajustando seu vestido, com uma expressão ansiosa no rosto. Embora ela realmente goste dessa roupa, ela precisará usá-la para receber os outros, e só de pensar no olhar do Navegador sobre ela, seus nervos ficam à flor da pele. Agora, tudo o que ela quer é encontrar um canto escuro para se esconder.",
  str_book_skin_info_10050 = "Ao anoitecer, você se aconchega em volta da fogueira, refletindo sobre experiências recentes. Você ouve em silêncio enquanto Gram compartilha suas histórias dos jovens soldados que encontrou após se tornar instrutor: Alguns trilharam caminhos de glória, enquanto outros tiveram fins prematuros em batalhas recentes.",
  str_book_skin_info_10051 = "Ao rugir de vida, o Aspirador de Pó Eclipsita, Revy derrota rapidamente todos os inimigos à frente. Então, conforme o pedido de Gronru, Revy prontamente faz uma pose arrojada, e Gronru aproveita o momento para encerrar a sessão de fotos publicitária.",
  str_book_skin_info_10052 = "Eles finalmente cavaram um buraco, e Ciel fica cara a cara com você e Gronru. Apesar de saber que Ciel estará segura, Gronru oferece a ela um abraço reconfortante para aliviar seu nervosismo. Com as emoções de Ciel acalmadas, ela prosseguirá guiando a equipe na próxima missão.",
  str_book_skin_info_10053 = "Ouvindo os sons misturados de marinheiros gritando e navios deixando o porto, Dantang podia sentir o entusiasmo dos marinheiros pela aventura de onde estava em um pavilhão.\nNo entanto, quando chega a hora de retornar, alguns desses navios voltam ao porto com ouro, prata, tesouros e histórias exóticas, enquanto alguns navios nunca retornam. É por isso que Dantang rezava silenciosamente pelos navios que saíam para o mar a partir do porto, enquanto segurava uma grade vermelha e os observava partir.\nEmbora navegar para o mar seja uma aventura e jornada para os corajosos, não se esqueça de que sempre há alguém observando por trás de você, esperando que seus entes queridos retornem.",
  str_book_skin_info_10054 = "Mal esperava Sariel que sua queda acidental não só resolveria o problema na casa de jogos, mas também faria com que sua recompensa de comissão fosse por água abaixo. Isso é sorte ou azar? Independentemente disso, Sariel se considera sortuda por ter enfrentado a crise com o Navegador.",
  str_book_skin_info_10055 = "Uma lâmina é fácil de sacar, mas difícil de guardar, pois o coração, e não a mão, é a chave para usar uma lâmina. Mesmo a lâmina mais afiada não seria páreo para um coração como este, pois as folhas de bambu já teriam caído antes que o pensamento surgisse...\nA lâmina ainda não foi sacada.",
  str_book_skin_info_10056 = "\"Abençoada pelo destino, a Donzela Dragão traz boas novas ao descer ao mundo.\"\n\"As ondas do vasto oceano são obscuras, como se envoltas em fumaça.\"\n\"A Donzela Dragão, um presente dos céus, traz inúmeras bênçãos para todos.\"\n\"Como uma jovem lua crescendo lentamente, ou o brilhante sol em sua ascensão.\"\n\"A Donzela Dragão, um presente dos céus, traz inúmeras bênçãos para todos.\"\n\"Como uma jovem lua crescendo lentamente, ou o brilhante sol em sua ascensão.\"",
  str_book_skin_info_10057 = "Sariel estava tão cheia de alegria, que não percebeu que a roupa preparada para ela pela loja era desesperadamente assimétrica até que ela a vestiu. Como alguém com tendências obsessivo-compulsivas, instantaneamente sentiu como se agulhas estivessem espetando todo o seu corpo, e ela queria rasgar imediatamente o tecido terrivelmente desequilibrado. No entanto, ela só ousou puxar a barra da saia para desabafar sua insatisfação, porque a loja a teria feito pagar pelos danos.",
  str_book_skin_info_10058 = "Os soldados sereianos atrás de Tianxian o perseguem desesperadamente para tirar as roupas glamourosas do Palácio do Dragão dele e jogá-lo na prisão. Tianxian não está com disposição para discutir, e a coisa mais importante para ele agora é escapar do Palácio do Dragão. No entanto, para as pessoas que já experimentaram as vicissitudes da vida, entrar no palácio é fácil, mas sair é uma questão completamente diferente...",
  str_book_skin_info_10059 = "Os biscoitos festivos recém-assados exalam um aroma sedutor, e o calor suave que emana é suficiente para dissipar o frio da casa. Os biscoitos foram assados pelas crianças do orfanato, e Lilica compartilhou-os com você porque ela acha que você merece metade do crédito pelo sucesso da apresentação. Que May este biscoito dissipe o frio e traga boa sorte neste tempo frio.",
  str_book_skin_info_10060 = "Com uma velocidade relâmpago, Hiiro desembainha sua lâmina e transforma os atacantes em pó, não deixando nenhum sinal de sua existência. Seu traje elegante torna sua presença impressionante ainda mais pitoresca.",
  str_book_skin_info_10061 = "A luz suave da fogueira lança uma cor estranha no rosto de Hiiro. Talvez seja a cor das flores de cerejeira que floresceram cedo em um lugar distante, ou a cor das emoções poderosas que esta bela senhora é tímida demais para expressar.",
  str_book_skin_info_10062 = "Pollux conta a você como crises passadas a levaram a se tornar uma protetora. Ela não quer se apegar às memórias, no entanto, pois ela antecipa a criação de um futuro melhor com você.",
  str_book_skin_info_10063 = "Enquanto Areia realmente aproveita o tempo maravilhoso com você nos sonhos, eles estão destinados a desaparecer. A realidade a mergulhou em confusão. Depois de se banhar em luz solar genuína e respirar uma brisa marinha refrescante, Areia finalmente entende que a bondade e a felicidade sempre estiveram ao seu redor.",
  str_book_skin_info_10064 = "Xuan Ji lhe presenteia com este guarda-sol, bem como o sonho que ele representa. Seja uma terra distante ou as estrelas sempre distantes acima, nada está realmente fora de alcance, desde que você o deseje.",
  str_book_skin_info_10065 = "Cada frase, cada palavra, cada caractere do passado pode potencialmente ser um sinal deixado por nossos antecessores em sua jornada em busca da verdade. O que moldou cada caractere e que significado ele poderia possivelmente ter - todas as respostas estão em cada traço.",
  str_book_skin_info_10066 = "O que poderia ser mais confortável do que deitar aqui em êxtase?\nSem tarefas para completar, sem batalhas para lutar e sem necessidade de buscar um significado para qualquer coisa - o único significado deste momento é simplesmente se soltar e aproveitar.\nVeja, até a pomba branca que voa fora da minha janela concorda.",
  str_book_title_skin_50001 = "Dia no aquário",
  str_book_skin_info_50001 = "Essa peça de roupa veio primeiro ou o jogo que veio com essa roupa veio primeiro? Não importa mais. O importante é que Gronru preparou isso especialmente para suas férias e entrou no modo de férias logo após usá-lo, mesmo que ela esteja indo para o aquário e não para a praia em suas férias.",
  str_book_title_skin_50002 = "Serendipidade fofa",
  str_book_title_skin_50003 = "Nascido para agir",
  str_book_title_skin_50004 = "Abraço da doce melodia",
  str_book_title_skin_50005 = "Caprichoso embriagado",
  str_book_saiji_info_20001 = "Na memória de Eve, esta é sua casa feliz. Mas algo estava faltando. Talvez algo tenha sido esquecido, ou talvez alguém tenha se perdido...",
  str_book_saiji_info_20002 = "As memórias finalmente foram apagadas e Eve se reuniu com sua amada família. Esperança e felicidade, prosperando ao sol, se tornaram flores brancas em plena floração.",
  str_book_saiji_info_20003 = "Eve \"acorda\" de um sonho intenso e se encontra em um ambiente familiar, mas ao mesmo tempo desconhecido. Será este o seu próprio quarto?",
  str_book_saiji_info_20004 = "Um enorme rastreador de aço se arrasta no topo da montanha. Quem é o criador de tal máquina? E para que fim foi construída? Uma sensação de déjà vu invade Eve; a cena parece familiar, mas ela não consegue identificar onde já a encontrou antes...",
  str_book_saiji_info_20005 = "Assim que o colapso iminente ameaçou Eve, um escudo de flores brancas familiares e vinhas robustas surgiu misteriosamente. De onde poderiam ter brotado?",
  str_book_saiji_info_20006 = "Os dois Eves finalmente se unem, preparados para enfrentar sua verdadeira realidade.",
  str_book_saiji_info_20007 = "O mundo distorcido desapareceu, deixando Eve com uma sensação de alívio. Embora o caminho à frente possa estar repleto de obstáculos, também brilha com um potencial ilimitado.",
  str_book_saiji_info_20101 = "A luz do sol atravessa o vidro colorido, iluminando o ambiente escuro e silencioso com um deslumbrante conjunto de cores. Ela toca suavemente as pálpebras de Irridon, que abre os olhos. É então que ela vê, o reflexo de uma mulher no espelho.",
  str_book_saiji_info_20102 = "Irridon sabe que a pessoa no espelho não é ela mesma, mas por algum motivo, ela sente que seu destino está intimamente entrelaçado com o do reflexo. Então, a chama da vela se acende, iluminando a imagem pura e tranquila de uma freira na parede.",
  str_book_saiji_info_20103 = "Irridon recorda a identidade da figura no espelho e finalmente lembra quem ela mesma é. A vela do outro lado é acesa, revelando uma imagem solene e imponente da Juíza Chefe no mural.",
  str_book_saiji_info_20104 = "Ao olhar seu reflexo na piscina, Irridon de repente sente um momento de introspecção... O que a levou a se tornar quem ela é hoje? Será que o reflexo na piscina é realmente a imagem que ela aspira ser?",
  str_book_saiji_info_20105 = "A mulher de preto à sua frente entra em ação, seguida por inúmeras vinhas espinhosas surgindo de todas as direções. Irridon entende que a mulher carrega em seu coração uma escuridão mais afiada e negra do que esses espinhos.",
  str_book_saiji_info_20106 = "De qualquer forma, Irridon não pode ficar parado e assistir a mulher à sua frente cometer um erro tão grave.",
  str_book_saiji_info_20107 = "Vencer a si mesmo não é uma tarefa fácil, mas Irridon finalmente conseguiu.",
  str_book_saiji_info_20108 = "Este árduo julgamento finalmente chegou ao fim. Embora o caminho à frente seja longo, Irridon não se perderá mais.",
  str_book_cg_no_collect = "Não Coletado",
  str_book_cg_no_collect_msg = "Conc. os cenários {1}{2} p/ desb.",
  str_book_world = "Mundo",
