  str_book_monster_dont_have = "Essa informação não foi coletada.",
  str_book_btn_monster_lock = "-Não Coletado-",
  str_book_main_mark = "Parede do Emblema",
  str_book_main_huodong = "Recap. do Evento",
  str_book_main_lock = "Trancado",
  str_book_ext_cg_active = "Conc. os capítulos extras p/ desb.",
  str_book_main_cg_active = "Conc. o capítulos principais p/ desb.",
  str_book_pet_skin_cg_active = "Conc. o cenário do Traje de Colec. p/ desbloquear.",
  str_book_pet_skin_cell_cg_active = "Desbl. após comprar o Traje de Colecionador.",
  str_book_cg_pet_skin = "Traje",
  str_book_no_camp = "-Sem Facção-",
  str_book_not_open = "Trancado Temp.",
  str_book_main_medal = "Medalha Fique Comigo",
  str_book_season_cg_active = "DNT",
  str_book_unlock_desc_20001 = "Obtido após ler o prelúdio de N1-Sonho Bizarro no Despertar na Tempestade",
  str_book_unlock_desc_20002 = "Obtido ao adquirir o Complete Sketchbook colecionável em Awakening in the Storm",
  str_book_unlock_desc_20003 = "Obtido após ler o prelúdio de N1-Sonho Bizarro no Despertar na Tempestade",
  str_book_unlock_desc_20004 = "Obtido após ler a prequela de N7-Red Hound em Awakening in the Storm",
  str_book_unlock_desc_20005 = "Obtido após ler a sequência de N8-Catch Fire em Awakening in the Storm",
  str_book_unlock_desc_20006 = "Obtido ao adquirir o Complete Sketchbook colecionável em Awakening in the Storm",
  str_book_unlock_desc_20007 = "Obtido ao adquirir o Complete Sketchbook colecionável em Awakening in the Storm",
  str_book_unlock_desc_20101 = "Obtido após ler o prelúdio de N1 - Cavaleiro em Provas Entre Ondulações Douradas.",
  str_book_unlock_desc_20102 = "Obtido após ler o prelúdio de N10 - Conspiração Rebelde em Testes Entre Ondulações Douradas.",
  str_book_unlock_desc_20103 = "Obtido após ler a sequência de N15 - Julgamento Final em Julgamentos Entre Ondulações Douradas.",
  str_book_unlock_desc_20104 = "Obtido após ler o prelúdio de N1 - Cavaleiro em Provas Entre Ondulações Douradas.",
  str_book_unlock_desc_20105 = "Obtido após ler o prelúdio de N14 - O Reflexo nas Provações Entre Ondulações Douradas.",
  str_book_unlock_desc_20106 = "Obtido após ler o prelúdio de N14 - O Reflexo nas Provações Entre Ondulações Douradas.",
  str_book_unlock_desc_20107 = "Obtido após ler a sequência de N15 - Julgamento Final em Julgamentos Entre Ondulações Douradas.",
  str_book_unlock_desc_20108 = "Obtido após ler a sequência de N15 - Julgamento Final em Julgamentos Entre Ondulações Douradas.",
  str_book_title_skin_10068 = "Convite Embriagado",
  str_book_skin_info_10068 = "\"O tempo de uma bruxa é valioso e eu não posso esperar, tsk-tsk.\"\nApós beber uma poção mágica, Uriel de repente se torna proativo, não apenas te encurralando, mas também tentando algo ainda mais terrível...",
  str_book_title_skin_10069 = "Sinos ao Crepúsculo",
  str_book_skin_info_10069 = "\"Eu mesmo acabei de perceber - e realmente foi um segundo atrás - que o vazio poderia ser preenchido.\"\nO calor das chamas desfoca a figura da bruxa. Mas qual delas está se confessando para você agora?",
  str_book_title_skin_10067 = "Sensibilidade de Axelia",
  str_book_skin_info_10067 = "Uma sensação mágica atingiu Axelia, entrelaçando seu eu fragmentado com a rosa confinada no frasco de vidro. Este inexplicável surto de emoção sinaliza as mudanças emergentes em sua mentalidade.",
  str_book_title_skin_10070 = "Estimado",
  str_book_skin_info_10070 = "\"Era um campo de trigo! Cheio de grãos dourados e oscilantes, e eu estava lá! Ao meu lado estava uma senhora gentil cujo rosto não estava claro para mim, mas ela estava sorrindo para mim. Muitas crianças estavam correndo ao nosso redor... O riso delas ecoava pelo campo como uma canção.\"",
  str_book_title_skin_10071 = "Testemunha do Ídolo Dragão",
  str_book_title_skin_10072 = "Soneca do Meio-dia de Robyn",
  str_book_skin_info_10071 = "\"Pode parecer um pouco arrogante da minha parte dizer isso, mas eu realmente espero poder me tornar alguém em quem você possa confiar.\"\nSob a testemunha do ídolo do dragão, você estende um convite para Sharona.",
  str_book_skin_info_10072 = "Perdida no mundo dos livros, Robyn cochila na mesa. A luz do sol do meio-dia é radiante, mas seu sono não é perturbado.",
  str_book_info1108 = "Desejo",
  str_book_info1109 = "Destrua a Escuridão",
  str_book_info1110 = "Refúgio",
  str_book_info1111 = "Refúgio - Farol",
  str_book_info1112 = "Votos na Cordilheira",
  str_book_title1108 = "Carregando um dever indescritível, ela se ajoelha diante do altar, sua tristeza não expressa, mas profundamente sentida, oferecendo fervorosas orações ao divino. Este ritual misterioso e comovente se desenrola como uma obra-prima melancólica.",
  str_book_title1109 = "No meio da escuridão, ela salta como um relâmpago, sua lança mergulha impiedosamente no crânio do inimigo. Com uma ferocidade e força indomáveis, ela sacode a própria terra, seus olhos em chamas com um ódio vingativo queimando seus adversários.",
  str_book_title1110 = "Liderado pelo espírito das montanhas, o poder da natureza flui para a base, e aglomerados de luz fluindo irrompem dos tocos de árvores, iluminando o vasto altar. Assim, os espíritos há muito silenciados são despertados.",
  str_book_title1111 = "Em um instante, três pinheiros antigos brotam em uma árvore imponente como um farol, seu brilho radiante ilumina toda a caverna, com o raio mais suave infundindo a lança de Tiare.",
  str_book_title1112 = "\"Para erguer faróis ao longo do caminho à frente.\"\nA bandeira tremulante testemunha e torce por eles, levando seus votos para terras distantes.",
  str_book_title_skin_10073 = "Luz de Fluorita",
  str_book_skin_info_10073 = "Você conversa até tarde da noite com Fleur sobre minerais quando o minério emite um brilho fraco - espere, por que ainda está quente? Julgando pela expressão de Fleur, ele poderia estar com febre?",
  str_book_title_skin_10074 = "Jogos do Dormitório",
  str_book_skin_info_10074 = "\"Agora que te capturei, você tem que tocar o coração na mesa para se libertar!\"",
  str_book_title_skin_10075 = "Noite Estrelada Insonia",
  str_book_skin_info_10075 = "\"Com você ao meu lado, não importa o quão escuro esteja, eu não acho que tenho algo a temer!\"",
  str_book_title_skin_10077 = "Bela Adormecida e o Príncipe",
  str_book_skin_info_10077 = "\"Estou ainda sonhando? Tudo parece tão real, desde o seu calor até a sua respiração...\"",
  str_book_title_skin_10078 = "Vamos Fazer Isso",
  str_book_skin_info_10078 = "A porta se abre de repente, interrompendo os passos hesitantes da garota. Nesse caso, ela só pode engolir o choro e seguir em frente com a cabeça erguida. A garota aperta os lábios, determinada a não deixar ninguém ver sua confusão e impotência.",
  str_book_title_skin_10079 = "Dança do Caracol do Rio da Donzela Dragão",
  str_book_skin_info_10079 = "\"Ao realizar sua dança sagrada aqui, os caracóis farão o que eu ordenar por reverência.\"",
  str_book_title_skin_10080 = "Besta Engaiolada",
  str_book_skin_info_10080 = "Hydrad infiltrou-se sozinho em suas fileiras e está contando com você para vir com reforços.",
  str_book_title_skin_10081 = "Mini Deidade",
  str_book_skin_info_10081 = "\"Sua oferta me agradou muito. Fale seu desejo, e eu o realizarei para você.\"",
  str_book_title_skin_10082 = "Cores Florescentes",
  str_book_skin_info_10082 = "\"May toda a beleza do mundo dance em seu nome, e May sua sábia liderança floresça por mil anos.\"",
  str_book_title_skin_10084 = "Observador Yingel",
  str_book_skin_info_10084 = "\"Como você pode ver, estou observando a Rediesel Wrench em seu habitat natural.\"",
  str_book_title_skin_10085 = "Apresentando com Barbara",
  str_book_skin_info_10085 = "O show de Barbara começa com um estrondo! \"O Último Celestita\" está realmente estreando com ela?",
  str_book_title_skin_10086 = "Jeriah na Praia",
  str_book_skin_info_10086 = "\"Seja você ou nossos arredores... Tudo é novo para mim.\"",
  str_book_title_skin_10087 = "Estrela do Banquete",
  str_book_skin_info_10087 = "\"Abordá-lo é perfeitamente aceitável, mas peço que se comportem com um pouco mais de dignidade.\"",
  str_book_title_skin_10088 = "Silhueta da Iluminação Iluminada",
  str_book_skin_info_10088 = "\"Como Grande Marechal da Federação Illumina... Eu juro vigiar tudo.\"",
  str_book_title_skin_10090 = "Inflexível ao Tempo",
  str_book_skin_info_10090 = "\"As crianças da 2ª Legião... Vocês se tornaram as estrelas que iluminam o caminho dos outros?\"",
  str_book_title_skin_10091 = "Gêmeas da Flor Branca",
  str_book_skin_info_10091 = "\"Parecemos tanto um com o outro; até nossos pais têm dificuldade em nos distinguir...\"",
  str_book_title_skin_10092 = "Corrida na Areia",
  str_book_skin_info_10092 = "\"A arma agora está disparando água em vez de chamas. Se... apenas esse tipo de diversão pudesse durar para sempre. Uma águia ainda pode voar alto mesmo com suas garras recolhidas.\"",
  str_book_title_skin_10095 = "Ryza's Dia Preguiçoso",
  str_book_skin_info_10095 = "\"Você me chamou? E aí?\"",
  str_book_title_skin_10096 = "Os Fogos de Artifício em Seus Olhos",
  str_book_skin_info_10096 = "\"Fogos de artifício podem ser breves, mas eles sempre cintilarão em meu coração.\"",
  str_book_title_skin_10097 = "O Dignitário Encharcado",
  str_book_skin_info_10097 = "\"Quer dizer, se você pedisse tão sinceramente como fez antes, eu, um nobre, poderia reservar algum tempo para me divertir com você.\"",
  str_book_title_skin_10099 = "Encontro Casual: Bola de Neve",
  str_book_skin_info_10099 = "\"Por favor, siga a direção para a qual estou te guiando. Sinta a flutuação das ondas. Não tenha medo, eu vou segurar sua mão.\"",
