  str_book_title_skin_laisha2 = "\"Fireworks may be brief, but they'll forever flicker in my heart.\"",
  str_book_info_laisha1 = "Encontro Varrido pelas Ondas",
  str_book_title_laisha1 = "\"Pensei que estivéssemos brincando, não estávamos? Melhor se mexer, ou eu realmente vou te pegar! Hah!\"",
  str_book_info_laisha2 = "Reunindo Pensamentos",
  str_book_title_laisha2 = "\"E que tal? Você consegue sentir nossa determinação agora?!\"",
  str_book_info_laisha3 = "Nova Aventura! Vamos Navegar!",
  str_book_title_laisha3 = "A ilha repousa silenciosamente no fundo do mar, junto com as evidências de sua antiga glória. Agora, uma nova aventura de verão está prestes a começar.",
  str_book_title_skin_10100 = "Proposta Ambiciosa",
  str_book_skin_info_10100 = "Quer sair em um encontro? Lembre-se de trazer moedas de ouro suficientes!",
  str_book_title_skin_10101 = "Indulgência Carmesim",
  str_book_skin_info_10101 = "O Rei Que Retorna do Banquete Sangrento",
  str_book_title_skin_10102 = "Traços de Aço",
  str_book_skin_info_10102 = "Não fique nervoso, tome primeiro uma garrafa de solução nutritiva!",
  str_book_title_skin_10103 = "Lachesis Ganancioso",
  str_book_skin_info_10103 = "\"Por baixo de seu charme gracioso e tentador, uma luz gananciosa cintila. Fique atento, ou ela vai arrancar tudo o que você preza!\"",
  str_book_info1113 = "Viva Livre ou Morra",
  str_book_title1113 = "\"O 'coração' dela arde em chamas, nunca se cansando em sua busca pela liberdade.\nEla dará sua vida por essa verdade.\n'Viva livre ou morra', disse a Senhora Pepita.\""
